import{_ as p,a0 as r,w as l,s,ao as d,I as a,x as e,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Linux 上用 IP转发使内部网络连接到互联网 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上用 IP转发使内部网络连接到互联网 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上用 IP转发使内部网络连接到互联网 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上用 IP转发使内部网络连接到互联网 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150423 How IP forwarding Helps Connecting Private interface to Internet in Linux","title":"如何在 Linux 上用 IP转发使内部网络连接到互联网","tag":"201506","desc":""},"relativePath":"201506/20150423 How IP forwarding Helps Connecting Private interface to Internet in Linux.md","filePath":"[post].md"}'),c={name:"201506/20150423 How IP forwarding Helps Connecting Private interface to Internet in Linux.md"};function f(g,t,u,x,m,h){const n=r("Link");return l(),s("div",null,[t[13]||(t[13]=d(`<h1 id="如何在-linux-上用-ip转发使内部网络连接到互联网" tabindex="-1">如何在 Linux 上用 IP转发使内部网络连接到互联网 <a class="header-anchor" href="#如何在-linux-上用-ip转发使内部网络连接到互联网" aria-label="Permalink to “如何在 Linux 上用 IP转发使内部网络连接到互联网”">​</a></h1><p>大家好，今天我们学习一下在 Linux 上用 iptables 实现从一个网络接口到另一个接口的IP转发（数据包转发）。IP转发的概念是，使 Linux 机器像路由器一样将数据从一个网络发送到另一个网络。所以，它能作为一个<strong>路由器</strong>或者代理服务器，实现将一个连接的互联网或者网络连接共享给多个客户端机器。</p><p>这是一些启用IP转发或网络包转发方法的简单步骤。</p><h3 id="_1-启用-ipv4-转发" tabindex="-1">1. 启用 IPv4 转发 <a class="header-anchor" href="#_1-启用-ipv4-转发" aria-label="Permalink to “1. 启用 IPv4 转发”">​</a></h3><p>首先，我们需要在我们的 Linux 操作系统上启用 IPv4 转发。要做到这点，我们需要用 sudo 模式在 shell 或终端下执行下面的命令。</p><pre><code>$ sudo -s

# echo 1 &gt; /proc/sys/net/ipv4/ip_forward
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ip-forward-temporary.png" alt="临时IP转发"></p><p><strong>注意：上面的命令能马上启用ip转发，但只是临时的，直到下一次重启。要永久启用，我们需要使用我们惯用的文本编辑器打开 /etc/sysctl.conf 文件。</strong></p><pre><code># nano /etc/sysctl.conf
</code></pre><p>然后，增加 <strong>net.ipv4.ip_forward = 1</strong> 到文件中，或者删除那行的注释，保存并退出文件。</p><pre><code>net.ipv4.ip_forward = 1
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/sysctl-edit.png" alt="编辑 Sysctl"></p><p>运行下面的命令启用更改。</p><pre><code># sysctl -p /etc/sysctl.conf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/enabling-changes-sysctl.png" alt="启用 Sysctl 更改"></p><h3 id="_2-配置-iptables-防火墙" tabindex="-1">2. 配置 Iptables 防火墙 <a class="header-anchor" href="#_2-配置-iptables-防火墙" aria-label="Permalink to “2. 配置 Iptables 防火墙”">​</a></h3><p>我们需要允许特定的(或者所有的)数据包通过我们的路由器。在这之前，我们要知道连接我们 Linux 的网络设备的接口名称。我们可以通过在终端或者 shell 运行以下命令获得接口名称。</p><pre><code># ifconfig -a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ifconfig.png" alt="Ifconfig"></p><p>这里，在我们的机器中， eth2 是连接到互联网或者网络的网卡接口， wlan2 是我们要使用 iptables 从 eth2 转发数据包的接口。要实现转发，我们需要运行以下命令。</p><pre><code># iptables -A FORWARD -i wlan2 -o eth2 -j ACCEPT
</code></pre><p>注意：请用你 Linux 机器中的可用设备名称替换 wlan2 和 eth2。</p><p>现在，由于netfilter/iptables是一个无状态的防火墙，我们需要让 iptables 允许已建立的连接通过。要做到这点，我们要运行下面的命令。</p><pre><code># iptables -A FORWARD -i eth2 -o wlan2 -m state --state ESTABLISHED,RELATED  -j ACCEPT
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/forwarding-iptables.png" alt="用 iptables 转发"></p><h3 id="_3-配置-nat" tabindex="-1">3. 配置 NAT <a class="header-anchor" href="#_3-配置-nat" aria-label="Permalink to “3. 配置 NAT”">​</a></h3><p>然后，最后我们需要通过执行下面的命令修改发送到互联网的数据包的源地址为 eth2。</p><pre><code># iptables -t nat -A POSTROUTING -o eth2 -j MASQUERADE
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/configuring-nat.png" alt="配置 nat"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>最后，我们在我们以 iptables 作为防火墙 Linux 机器上成功的配置了从一个接口到另一个接口的数据包转发。这篇文章教给你将你的私有接口连接到互联网，不需要桥接接口，而是将从一个接口进来的数据包路由到另一个接口。就是这些，如果你有任何问题、建议、反馈，请写到下面的评论框中，然后我们可以改进或更新我们的内容。非常感谢！享受吧 😃</p><hr>`,32)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),i(n,{href:"http://linoxide.com/firewall/ip-forwarding-connecting-private-interface-internet/"},{default:o(()=>[...t[0]||(t[0]=[e("http://linoxide.com/firewall/ip-forwarding-connecting-private-interface-internet/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),i(n,{href:"http://linoxide.com/author/arunp/"},{default:o(()=>[...t[2]||(t[2]=[e("Arun Pyasi",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),i(n,{href:"https://github.com/ictlyh"},{default:o(()=>[...t[3]||(t[3]=[e("ictlyh",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),i(n,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const T=p(c,[["render",f]]);export{w as __pageData,T as default};
